<?php

use App\Models\TransportLine;
use Illuminate\Database\Seeder;
use Illuminate\Support\Arr;
use App\Models\Group;
use App\Models\PathPoint;
use App\Models\Route;

class GroupRouteSeeder extends Seeder
{
    /**
     * Run the database seeds.
     *
     * @return void
     */
    public function run()
    {
        $groupsToInsert = $this->getGroups();
        foreach($groupsToInsert as $groupData){
            $group = new Group();
            $group->name = Arr::get($groupData, "name", "---");
            $group->logo_path = '';
            $group->save();
            foreach(Arr::get($groupData, "features", []) as $routeData){
                $name = Arr::get($routeData, "properties.Name", "L 00 S");
                $lineData = explode(' ', $name);
                if(count($lineData)>=3){
                    $code = $lineData[1];
                    $type = $lineData[2];
                    $color = Arr::get($routeData, "color", "#000000") ;
                    $notes = Arr::get($routeData, "notes", "");

                    $transportLine = TransportLine::where([
                        ['code', '=', $code],
                        ['color', '=', $color]
                    ])->first();
                    if(!$transportLine){
                        $transportLine = new TransportLine();
                        $transportLine->code = $code;
                        $transportLine->color = $color;
                        $transportLine->group_id = $group->id;
                        $transportLine->save();
                    }
                    $route = new Route();
                    $route->type = $type;
                    if(strlen($notes)>0){
                        $route->notes = $notes;
                        $route->enabled = false;
                    }
                    $route->transport_line_id = $transportLine->id;
                    $route->save();
                    foreach(Arr::get($routeData, "geometry.coordinates", []) as $index => $lngLat){
                        $point = new PathPoint();
                        $point->order = $index + 1;
                        $point->lat = $lngLat[1];
                        $point->lng = $lngLat[0];
                        $point->route_id = $route->id;
                        $point->save();
                    }
                }
            }
        }
    }

